13	import NotebookTab from './NotebookTab/NotebookTab';
14	
15	interface ChatMessage {
16	    id: string;
17	    role: 'user' | 'nexus';
18	    content: string;
19	    streaming?: boolean;
20	    timestamp: string;
21	    files?: UploadedFile[];
22	}
23	
24	interface UploadedFile {
25	    name: string;
26	    type: string;
27	    dataUrl: string;
28	    size: number;
29	}
30	
31	interface ImageModel {
32	    id: string;
33	    label: string;
34	    provider: string;
35	}
36	
37	type TabId = 'context' | 'research' | 'code' | 'visual' | 'ops' | 'notebook';
38	
39	const TABS: { id: TabId; label: string; icon: string }[] = [
40	    { id: 'context',  label: 'Context',  icon: '◈' },
41	    { id: 'research', label: 'Research', icon: '◎' },
42	    { id: 'code',     label: 'Code',     icon: '⬡' },
43	    { id: 'visual',   label: 'Visual',   icon: '◆' },
44	    { id: 'ops',      label: 'Ops',      icon: '◉' },
45	    { id: 'notebook', label: 'Notebook', icon: '◧' }
46	];
47	
48	const REASONING_LEVELS = ['low', 'medium', 'high', 'council'] as const;
49	type ReasoningLevel = typeof REASONING_LEVELS[number];
50	
51	const REASONING_COLORS: Record<ReasoningLevel, string> = {
52	    low:     'var(--text-dim)',
53	    medium:  'var(--cyan-glow)',
54	    high:    'var(--gold-solar)',
55	    council: 'var(--red-fusion)'
56	};
57	
58	export default function OraclePage() {
59	    const [messages, setMessages] = useState<ChatMessage[]>([{
60	        id: 'boot',
61	        role: 'nexus',
62	        content: 'NEXUS — Oracle online. All systems nominal. What directive shall I process?',
63	        timestamp: new Date().toISOString()
64	    }]);
65	    const [input, setInput]           = useState('');
66	    const [activeTab, setActiveTab]   = useState<TabId>('context');
67	    const [reasoning, setReasoning]   = useState<ReasoningLevel>('medium');
68	    const [terminalOpen, setTerminalOpen] = useState(false);
69	    const [dragOver, setDragOver]     = useState(false);
70	    const [pendingFiles, setPendingFiles] = useState<UploadedFile[]>([]);
71	    const [isListening, setIsListening] = useState(false);
72	    const [imageModels, setImageModels] = useState<{ kie: ImageModel[]; remote: ImageModel[] }>({ kie: [], remote: [] });
73	    const [oracleState, setOracleState] = useState<OracleCommandState | null>(null);
74	    const [models, setModels]          = useState<any[]>([]);
75	    const [selectedModel, setSelectedModel] = useState<string>('qwen-liberated:latest');
76	
77	    const chatEndRef   = useRef<HTMLDivElement>(null);
78	    const fileInputRef = useRef<HTMLInputElement>(null);
79	    const recognitionRef = useRef<any>(null);
80	
81	    // Subscribe to oracle state
82	    useEffect(() => {
83	        return subscribeOracleCommandState(setOracleState);
84	    }, []);
85	
86	    // Auto-scroll chat
87	    useEffect(() => {
88	        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
89	    }, [messages]);
90	
91	    // Load models + image model catalog
92	    useEffect(() => {
93	        apiFetch('/api/neural/models').then(r => r.json()).then(d => { if (Array.isArray(d)) setModels(d); }).catch(() => {});
94	        apiFetch('/api/neural/images/models').then(r => r.json()).then(d => { if (d && Array.isArray(d.kie) && Array.isArray(d.remote)) setImageModels(d); }).catch(() => {});
95	    }, []);
96	
97	    const addMessage = useCallback((msg: ChatMessage) => {
98	        setMessages(prev => [...prev, msg]);
99	    }, []);
100	
101	    const updateLastNexus = useCallback((patch: Partial<ChatMessage>) => {
102	        setMessages(prev => {
103	            const idx = [...prev].reverse().findIndex(m => m.role === 'nexus');
104	            if (idx === -1) return prev;
105	            const realIdx = prev.length - 1 - idx;
106	            return prev.map((m, i) => i === realIdx ? { ...m, ...patch } : m);
107	        });
108	    }, []);
109	
110	    const handleSubmit = useCallback(async () => {
111	        const cmd = input.trim();
112	        if (!cmd && pendingFiles.length === 0) return;
113	        setInput('');
114	
115	        const userMsg: ChatMessage = {
116	            id: `u-${Date.now()}`,
117	            role: 'user',
118	            content: cmd || '[file upload]',
119	            timestamp: new Date().toISOString(),
120	            files: pendingFiles.length > 0 ? [...pendingFiles] : undefined
121	        };
122	        addMessage(userMsg);
123	        setPendingFiles([]);
124	
125	        const nexusId = `n-${Date.now()}`;
126	        addMessage({ id: nexusId, role: 'nexus', content: '', streaming: true, timestamp: new Date().toISOString() });
127	
128	        const useCouncil = reasoning === 'council';
129	
130	        if (!useCouncil) {
131	            // Streaming path — near-realtime
132	            try {
133	                await submitOracleCommandStream({
134	                    command: cmd || 'describe uploaded files',
135	                    source: 'typed',
136	                    modelId: selectedModel,
137	                    onChunk: (chunk) => {
138	                        if (chunk.type === 'token') {
139	                            setMessages(prev => prev.map(m =>
140	                                m.id === nexusId
141	                                    ? { ...m, content: m.content + (chunk.token || ''), streaming: true }
142	                                    : m
143	                            ));
144	                        } else if (chunk.type === 'done') {
145	                            setMessages(prev => prev.map(m =>
146	                                m.id === nexusId
147	                                    ? { ...m, content: chunk.content || m.content, streaming: false }
148	                                    : m
149	                            ));
150	                        } else if (chunk.type === 'error') {
151	                            setMessages(prev => prev.map(m =>
152	                                m.id === nexusId
153	                                    ? { ...m, content: `[Oracle error: ${chunk.error}]`, streaming: false }
154	                                    : m
155	                            ));
156	                        }
157	                    }
158	                });
159	            } catch (err: any) {
160	                updateLastNexus({ content: `[Stream failed: ${err.message}]`, streaming: false });
161	            }
162	        } else {
163	            // Council mode — blocking with phase display
164	            try {
165	                const result = await submitOracleCommand({
166	                    command: cmd,
167	                    source: 'typed',
168	                    useCouncil: true
169	                });
170	                const content = result?.response || result?.content || JSON.stringify(result);
171	                updateLastNexus({ content: String(content), streaming: false });
172	            } catch (err: any) {
173	                updateLastNexus({ content: `[Council error: ${err.message}]`, streaming: false });
174	            }
175	        }
176	    }, [input, pendingFiles, reasoning, selectedModel, addMessage, updateLastNexus]);
177	
178	    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
179	        if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSubmit(); }
180	    }, [handleSubmit]);
181	
182	    const handleFileDrop = useCallback((files: FileList | null) => {
183	        if (!files) return;
184	        const allowed = ['application/pdf', 'image/png', 'image/jpeg', 'image/gif', 'image/webp',
185	            'text/markdown', 'text/plain', 'application/x-python', 'text/x-python'];
186	        Array.from(files).forEach(file => {
187	            if (!allowed.some(t => file.type === t || file.name.endsWith('.md') || file.name.endsWith('.py') || file.name.endsWith('.ts'))) return;
188	            const reader = new FileReader();
189	            reader.onload = () => {
190	                setPendingFiles(prev => [...prev, {
191	                    name: file.name,
192	                    type: file.type,
193	                    dataUrl: reader.result as string,
194	                    size: file.size
195	                }]);
196	            };
197	            reader.readAsDataURL(file);
198	        });
199	    }, []);
200	
201	    const toggleVoice = useCallback(() => {
202	        const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
203	        if (!SR) return;
204	        if (isListening) {
205	            recognitionRef.current?.stop();
206	            setIsListening(false);
207	            return;
208	        }
209	        const rec = new SR();
210	        rec.lang = 'en-US';
211	        rec.continuous = false;
212	        rec.onresult = (e: any) => {
213	            const text: string = e.results[0]?.[0]?.transcript || '';
214	            setInput(prev => (prev + ' ' + text).trim());
215	            setIsListening(false);
216	        };
217	        rec.onend = () => setIsListening(false);
218	        rec.start();
219	        recognitionRef.current = rec as any;
220	        setIsListening(true);
221	    }, [isListening]);
222	
223	    const cycleReasoning = useCallback(() => {
224	        setReasoning(prev => {
225	            const idx = REASONING_LEVELS.indexOf(prev);
226	            return REASONING_LEVELS[(idx + 1) % REASONING_LEVELS.length];
227	        });
228	    }, []);
229	
230	    const isBusy = ['submitted', 'deliberating', 'stale'].includes(oracleState?.phase ?? '');
231	
232	    return (
233	        <div className="oracle-page" onDragOver={e => { e.preventDefault(); setDragOver(true); }}
234	            onDragLeave={() => setDragOver(false)}
235	            onDrop={e => { e.preventDefault(); setDragOver(false); handleFileDrop(e.dataTransfer.files); }}
236	        >
237	            {/* Drop overlay */}
238	            <AnimatePresence>
239	                {dragOver && (
240	                    <motion.div className="oracle-drop-overlay"
241	                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
242	                        <span>Drop files into NEXUS</span>
243	                    </motion.div>
244	                )}
245	            </AnimatePresence>
246	
247	            {/* Main layout */}
248	            <div className="oracle-layout">
249	
250	                {/* LEFT — Category tabs */}
251	                <div className="oracle-tabs">
252	                    {TABS.map(tab => (
253	                        <button key={tab.id} className={`oracle-tab ${activeTab === tab.id ? 'active' : ''}`}
254	                            onClick={() => setActiveTab(tab.id)}>
255	                            <span className="tab-icon">{tab.icon}</span>
256	                            <span className="tab-label">{tab.label}</span>
257	                            {tab.id === 'visual' && (imageModels.kie.length > 0 || imageModels.remote.length > 0) && (
258	                                <span className="tab-ready-dot" title="Image models loaded"/>
259	                            )}
260	                        </button>
261	                    ))}
262	                    <div className="oracle-tab-spacer"/>
263	                    <button className="oracle-tab terminal-toggle" onClick={() => setTerminalOpen(p => !p)}>
264	                        <span className="tab-icon">_</span>
265	                        <span className="tab-label">Terminal</span>
266	                    </button>
267	                </div>
268	
269	                {/* CENTER — Chat + orbs */}
270	                <div className="oracle-center">
271	
272	                    {/* Tool orbs or tab content */}
273	                    <div className="oracle-content-area">
274	                        {activeTab === 'visual' ? (
275	                            <VisualSynthesisLane models={imageModels} />
276	                        ) : activeTab === 'notebook' ? (
277	                            <NotebookTab />
278	                        ) : (
279	                            <OracleToolOrbs activeTab={activeTab as Exclude<TabId, 'notebook' | 'visual'>} />
280	                        )}
281	                    </div>
282	
283	                    {/* Chat thread */}
284	                    <div className="oracle-chat">
285	                        <div className="oracle-messages">
286	                            {messages.map(msg => (
287	                                <motion.div key={msg.id} className={`oracle-msg oracle-msg--${msg.role}`}
288	                                    initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}
289	                                    transition={{ duration: 0.2 }}>
290	                                    <span className="msg-label">
291	                                        {msg.role === 'user' ? 'NEXUS' : 'ORACLE'}
292	                                    </span>
293	                                    <div className="msg-body">
294	                                        {msg.content}
295	                                        {msg.streaming && <span className="cursor-blink">▋</span>}
296	                                    </div>
297	                                    {msg.files && msg.files.length > 0 && (
298	                                        <div className="msg-files">
299	                                            {msg.files.map((f, i) => (
300	                                                <span key={i} className="msg-file-pill">{f.name}</span>
301	                                            ))}
302	                                        </div>
303	                                    )}
304	                                </motion.div>
305	                            ))}
306	                            {isBusy && (
307	                                <div className="oracle-phase-indicator">
308	                                    <span className="phase-dot"/>
309	                                    {oracleState?.phase} · {oracleState?.elapsedMs ? Math.floor(oracleState.elapsedMs / 1000) + 's' : '...'}
310	                                </div>
311	                            )}
312	                            <div ref={chatEndRef}/>
313	                        </div>
314	
315	                        {/* Pending file pills */}
316	                        {pendingFiles.length > 0 && (
317	                            <div className="oracle-pending-files">
318	                                {pendingFiles.map((f, i) => (
319	                                    <span key={i} className="pending-file-pill">
320	                                        {f.name}
321	                                        <button onClick={() => setPendingFiles(p => p.filter((_, j) => j !== i))}>×</button>
322	                                    </span>
323	                                ))}
324	                            </div>
325	                        )}
326	
327	                        {/* Input bar */}
328	                        <div className="oracle-input-bar">
329	                            {/* Plus — file picker */}
330	                            <button className="input-action input-plus" onClick={() => fileInputRef.current?.click()} title="Attach file">
331	                                +
332	                            </button>
333	                            <input ref={fileInputRef} type="file" multiple hidden
334	                                accept=".pdf,.png,.jpg,.jpeg,.gif,.webp,.md,.py,.ts,.txt"
335	                                onChange={e => handleFileDrop(e.target.files)}/>
336	
337	                            <textarea
338	                                className="oracle-textarea"
339	                                value={input}
340	                                onChange={e => setInput(e.target.value)}
341	                                onKeyDown={handleKeyDown}
342	                                placeholder="Ask NEXUS..."
343	                                rows={1}
344	                            />
345	
346	                            {/* Model selector */}
347	                            <select className="oracle-model-select" value={selectedModel}
348	                                onChange={e => setSelectedModel(e.target.value)}>
349	                                {models.length > 0
350	                                    ? models.map((m: any) => <option key={m.id} value={m.id}>{m.name || m.id}</option>)
351	                                    : <option value="qwen-liberated:latest">Qwen Local</option>}
352	                            </select>
353	
354	                            {/* Reasoning level */}
355	                            <button className="input-action reasoning-level"
356	                                style={{ color: REASONING_COLORS[reasoning] }}
357	                                onClick={cycleReasoning}
358	                                title={`Reasoning: ${reasoning}`}>
359	                                {reasoning.slice(0, 3).toUpperCase()}
360	                            </button>
361	
362	                            {/* Mic */}
363	                            <button className={`input-action input-mic ${isListening ? 'active' : ''}`}
364	                                onClick={toggleVoice} title="Voice input">
365	                                {isListening ? '◉' : '🎤'}
366	                            </button>
367	
368	                            {/* Send */}
369	                            <button className="input-action input-send" onClick={handleSubmit} disabled={isBusy}>
370	                                {isBusy ? '⟳' : '↑'}
371	                            </button>
372	                        </div>
373	                    </div>
374	                </div>
375	            </div>
376	
377	            {/* Terminal pane (collapsible) */}
378	            <AnimatePresence>
379	                {terminalOpen && (
380	                    <motion.div className="oracle-terminal-pane"
381	                        initial={{ height: 0 }} animate={{ height: 320 }} exit={{ height: 0 }}
382	                        transition={{ duration: 0.25 }}>
383	                        <OracleTerminal />
384	                    </motion.div>
385	                )}
386	            </AnimatePresence>
387	
388	            <style>{ORACLE_STYLES}</style>
389	        </div>
390	    );
391	}
