import React, { useEffect, useRef } from 'react';

interface TopicNode { id: string; label: string; weight: number; }
interface TopicEdge { source: string; target: string; weight: number; }

interface NodeSim extends TopicNode {
    x: number; y: number;
    vx: number; vy: number;
}

export function NetworkGraph({ nodes, edges }: { nodes: TopicNode[]; edges: TopicEdge[] }) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const rafRef = useRef<number>(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas || !nodes.length) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const dpr = window.devicePixelRatio || 1;
        const w = canvas.clientWidth;
        const h = canvas.clientHeight;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        ctx.scale(dpr, dpr);

        // Initialize positions randomly
        const sims: NodeSim[] = nodes.map(n => ({
            ...n,
            x: w * 0.1 + Math.random() * w * 0.8,
            y: h * 0.1 + Math.random() * h * 0.8,
            vx: 0, vy: 0
        }));

        const idMap = new Map(sims.map(n => [n.id, n]));
        let frame = 0;

        function tick() {
            // Repulsion between nodes
            for (let i = 0; i < sims.length; i++) {
                for (let j = i + 1; j < sims.length; j++) {
                    const dx = sims[j].x - sims[i].x;
                    const dy = sims[j].y - sims[i].y;
                    const dist = Math.sqrt(dx * dx + dy * dy) || 1;
                    const force = 2000 / (dist * dist);
                    sims[i].vx -= (dx / dist) * force;
                    sims[i].vy -= (dy / dist) * force;
                    sims[j].vx += (dx / dist) * force;
                    sims[j].vy += (dy / dist) * force;
                }
            }

            // Attraction along edges
            for (const edge of edges) {
                const src = idMap.get(edge.source);
                const tgt = idMap.get(edge.target);
                if (!src || !tgt) continue;
                const dx = tgt.x - src.x;
                const dy = tgt.y - src.y;
                const dist = Math.sqrt(dx * dx + dy * dy) || 1;
                const target = 120;
                const force = (dist - target) * 0.02 * (edge.weight || 0.5);
                src.vx += (dx / dist) * force;
                src.vy += (dy / dist) * force;
                tgt.vx -= (dx / dist) * force;
                tgt.vy -= (dy / dist) * force;
            }

            // Center gravity
            const cx = w / 2, cy = h / 2;
            for (const n of sims) {
                n.vx += (cx - n.x) * 0.003;
                n.vy += (cy - n.y) * 0.003;
                n.vx *= 0.85;
                n.vy *= 0.85;
                n.x += n.vx;
                n.y += n.vy;
                n.x = Math.max(30, Math.min(w - 30, n.x));
                n.y = Math.max(20, Math.min(h - 20, n.y));
            }
        }

        function draw() {
            ctx.clearRect(0, 0, w, h);

            // Edges
            for (const edge of edges) {
                const src = idMap.get(edge.source);
                const tgt = idMap.get(edge.target);
                if (!src || !tgt) continue;
                ctx.beginPath();
                ctx.moveTo(src.x, src.y);
                ctx.lineTo(tgt.x, tgt.y);
                ctx.strokeStyle = `rgba(0,229,255,${(edge.weight || 0.5) * 0.4})`;
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            // Nodes
            for (const n of sims) {
                const r = 6 + (n.weight || 0.5) * 12;
                ctx.beginPath();
                ctx.arc(n.x, n.y, r, 0, Math.PI * 2);
                ctx.fillStyle = 'rgba(0,229,255,0.15)';
                ctx.fill();
                ctx.strokeStyle = '#00e5ff';
                ctx.lineWidth = 1.5;
                ctx.stroke();

                ctx.fillStyle = '#e8e8f0';
                ctx.font = '10px JetBrains Mono, monospace';
                ctx.textAlign = 'center';
                ctx.fillText(n.label.slice(0, 16), n.x, n.y + r + 12);
            }
        }

        function loop() {
            if (frame < 200) tick();
            draw();
            frame++;
            if (frame < 400) rafRef.current = requestAnimationFrame(loop);
        }

        rafRef.current = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(rafRef.current);
    }, [nodes, edges]);

    return (
        <canvas
            ref={canvasRef}
            style={{ width: '100%', height: '100%', display: 'block' }}
        />
    );
}

import React from 'react';

interface SentimentResult {
    positive: number;
    neutral: number;
    negative: number;
    compound: number;
}

export function SentimentGauge({ data }: { data: SentimentResult }) {
    const { positive, neutral, negative, compound } = data;
    const r = 80;
    const cx = 120;
    const cy = 110;
    const sweep = Math.PI;

    function arc(start: number, end: number, color: string) {
        const s = start * sweep;
        const e = end * sweep;
        const x1 = cx + r * Math.cos(Math.PI + s);
        const y1 = cy + r * Math.sin(Math.PI + s);
        const x2 = cx + r * Math.cos(Math.PI + e);
        const y2 = cy + r * Math.sin(Math.PI + e);
        const large = (e - s) > Math.PI ? 1 : 0;
        return `M ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2}`;
    }

    const neg = negative;
    const neu = neg + neutral;
    const pos = 1;

    // Pointer angle: compound -1→0, 0→0.5, 1→1
    const pointerNorm = (compound + 1) / 2;
    const pointerAngle = Math.PI + pointerNorm * sweep;
    const px = cx + (r - 12) * Math.cos(pointerAngle);
    const py = cy + (r - 12) * Math.sin(pointerAngle);

    return (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12 }}>
            <svg width={240} height={130} style={{ overflow: 'visible' }}>
                <path d={arc(0, neg)} stroke="#e55" strokeWidth={18} fill="none" strokeLinecap="butt" />
                <path d={arc(neg, neu)} stroke="#888" strokeWidth={18} fill="none" strokeLinecap="butt" />
                <path d={arc(neu, pos)} stroke="#9fe873" strokeWidth={18} fill="none" strokeLinecap="butt" />
                <line
                    x1={cx} y1={cy}
                    x2={px} y2={py}
                    stroke="#00e5ff" strokeWidth={3} strokeLinecap="round"
                />
                <circle cx={cx} cy={cy} r={5} fill="#00e5ff" />
                <text x={cx} y={cy + 24} textAnchor="middle" fill="#e8e8f0" fontSize={13} fontFamily="JetBrains Mono, monospace">
                    {compound >= 0 ? '+' : ''}{compound.toFixed(2)}
                </text>
            </svg>
            <div style={{ display: 'flex', gap: 20, fontSize: 11, fontFamily: 'JetBrains Mono, monospace', color: '#8888aa' }}>
                <span><span style={{ color: '#e55' }}>■</span> Negative {(negative * 100).toFixed(0)}%</span>
                <span><span style={{ color: '#888' }}>■</span> Neutral {(neutral * 100).toFixed(0)}%</span>
                <span><span style={{ color: '#9fe873' }}>■</span> Positive {(positive * 100).toFixed(0)}%</span>
            </div>
        </div>
    );
}

